CREATE SCHEMA IF NOT EXISTS industrendindia AUTHORIZATION CURRENT_USER; SET search_path TO industrendindia,pg_catalog;
CREATE TABLE IF NOT EXISTS app_config(config_key text PRIMARY KEY,config_value text NOT NULL,is_secret boolean NOT NULL DEFAULT false,description text,updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_by text NOT NULL DEFAULT current_user);
INSERT INTO app_config(config_key,config_value,description) VALUES ('auth.otp.ttl_seconds','300','OTP validity'),('auth.otp.resend_seconds','45','Minimum resend interval'),('auth.otp.max_attempts','5','Maximum verification attempts'),('auth.session.ttl_seconds','604800','Customer session lifetime'),('notification.provider','mock','mock or msg91'),('notification.msg91.base_url','https://control.msg91.com/api/v5/otp','MSG91 OTP endpoint'),('notification.msg91.template_id','','MSG91 OTP template id'),('notification.msg91.template_namespace','','MSG91 namespace'),('notification.msg91.sender_id','','MSG91 sender id') ON CONFLICT(config_key) DO NOTHING;
